<?php
declare(strict_types=1);
function app_statuses():array{return ['to_apply'=>'En préparation','applied'=>'Envoyée','waiting'=>'En attente','interview'=>'Entretien','proposal'=>'Proposition','rejected'=>'Refus','accepted'=>'Acceptée','archived'=>'Archivée'];}
function app_fetch(int $uid):array{$s=db()->prepare('SELECT a.*,o.title,o.company,o.city,o.source_url,sc.score AS match_score,sc.details_json AS match_details FROM applications a JOIN job_offers o ON o.id=a.job_offer_id LEFT JOIN offer_scores sc ON sc.job_offer_id=o.id AND sc.user_id=a.user_id WHERE a.user_id=? AND a.status<>\'to_review\' ORDER BY a.id DESC');$s->execute([$uid]);return $s->fetchAll();}
function app_ensure(int $uid,int $offer):int{$s=db()->prepare('SELECT id FROM job_offers WHERE id=? AND user_id=?');$s->execute([$offer,$uid]);if(!$s->fetchColumn())throw new InvalidArgumentException('Offre introuvable.');$s=db()->prepare('INSERT INTO applications(user_id,job_offer_id,status) SELECT user_id,id,status FROM job_offers WHERE id=? AND user_id=? ON DUPLICATE KEY UPDATE applications.id=LAST_INSERT_ID(applications.id)');$s->execute([$offer,$uid]);$s=db()->prepare('SELECT id FROM applications WHERE user_id=? AND job_offer_id=?');$s->execute([$uid,$offer]);return (int)$s->fetchColumn();}
function app_owned(int $uid,int $id):void{$s=db()->prepare('SELECT id FROM applications WHERE id=? AND user_id=?');$s->execute([$id,$uid]);if(!$s->fetchColumn())throw new InvalidArgumentException('Candidature introuvable.');}
function app_action(int $uid,array $p,array $files):void{
 $action=(string)($p['action']??'');$id=(int)($p['id']??0);if($action==='create'){$id=app_ensure($uid,(int)($p['offer_id']??0));return;}app_owned($uid,$id);
 if($action==='status'){$status=(string)($p['status']??'');if(!isset(app_statuses()[$status]))throw new InvalidArgumentException('Statut invalide.');db()->beginTransaction();try{$prev=db()->prepare('SELECT status FROM applications WHERE id=? AND user_id=? FOR UPDATE');$prev->execute([$id,$uid]);$previousStatus=(string)$prev->fetchColumn();if($previousStatus===$status){db()->commit();return;}$s=db()->prepare('UPDATE applications SET status=?,applied_at=CASE WHEN ?="applied" AND applied_at IS NULL THEN NOW() ELSE applied_at END WHERE id=? AND user_id=?');$s->execute([$status,$status,$id,$uid]);$s=db()->prepare('UPDATE job_offers o JOIN applications a ON a.job_offer_id=o.id SET o.status=? WHERE a.id=? AND a.user_id=?');$legacy=in_array($status,['waiting','proposal'],true)?'applied':$status;$s->execute([$legacy,$id,$uid]);$s=db()->prepare('INSERT INTO application_events(application_id,event_type,details) VALUES (?,?,?)');$s->execute([$id,'status',(app_statuses()[$previousStatus]??$previousStatus).' → '.app_statuses()[$status]]);db()->commit();}catch(Throwable $e){db()->rollBack();throw $e;}return;}
 if($action==='event'){$type=(string)($p['event_type']??'note');if(!in_array($type,['note','email','email_received','email_sent','call','meeting','other'],true))throw new InvalidArgumentException('Type invalide.');$details=trim((string)($p['details']??''));$subject=trim((string)($p['event_subject']??''));if($subject!=='')$details='Objet : '.mb_substr($subject,0,190)."\n".$details;if($details===''||mb_strlen($details)>5000)throw new InvalidArgumentException('Saisissez un commentaire (5000 caractères max).');$s=db()->prepare('INSERT INTO application_events(application_id,event_type,details) VALUES (?,?,?)');$s->execute([$id,$type,$details]);return;}
 if($action==='contact'){$name=mb_substr(trim((string)($p['full_name']??'')),0,160);if($name==='')throw new InvalidArgumentException('Nom requis.');$email=trim((string)($p['email']??''));if($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))throw new InvalidArgumentException('Email invalide.');$s=db()->prepare('INSERT INTO application_contacts(application_id,full_name,job_title,email,phone) VALUES (?,?,?,?,?)');$s->execute([$id,$name,mb_substr((string)($p['job_title']??''),0,160),$email,mb_substr((string)($p['phone']??''),0,60)]);return;}
 if($action==='interview'){$date=(string)($p['starts_at']??'');$d=DateTimeImmutable::createFromFormat('!Y-m-d\TH:i',$date);if(!$d||$d->format('Y-m-d\TH:i')!==$date)throw new InvalidArgumentException('Date invalide.');$mode=(string)($p['interview_mode']??'video');if(!in_array($mode,['telephone','video','onsite','other'],true))throw new InvalidArgumentException('Format invalide.');$s=db()->prepare('INSERT INTO application_interviews(application_id,starts_at,interview_mode,location,notes) VALUES (?,?,?,?,?)');$s->execute([$id,$d->format('Y-m-d H:i:s'),$mode,mb_substr((string)($p['location']??''),0,255),mb_substr((string)($p['notes']??''),0,5000)]);return;}
 if($action==='reminder'){$date=(string)($p['due_at']??'');$d=DateTimeImmutable::createFromFormat('!Y-m-d\TH:i',$date);if(!$d||$d->format('Y-m-d\TH:i')!==$date)throw new InvalidArgumentException('Date invalide.');$title=mb_substr(trim((string)($p['title']??'')),0,200);if($title==='')throw new InvalidArgumentException('Titre requis.');$s=db()->prepare('INSERT INTO application_reminders(application_id,due_at,title) VALUES (?,?,?)');$s->execute([$id,$d->format('Y-m-d H:i:s'),$title]);return;}
 if($action==='reminder_done'){$s=db()->prepare('UPDATE application_reminders SET done=1 WHERE id=? AND application_id=?');$s->execute([(int)($p['reminder_id']??0),$id]);return;}
 if($action==='upload'){$f=$files['document']??null;if(!$f||$f['error']!==UPLOAD_ERR_OK)throw new InvalidArgumentException('Échec du transfert.');if($f['size']>5*1024*1024)throw new InvalidArgumentException('Fichier limité à 5 Mo.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$ext=['application/pdf'=>'pdf','application/vnd.openxmlformats-officedocument.wordprocessingml.document'=>'docx','application/msword'=>'doc'][$mime]??null;if(!$ext)throw new InvalidArgumentException('Seuls PDF, DOC et DOCX sont autorisés.');$type=(string)($p['document_type']??'other');if(!in_array($type,['cv','letter','other'],true))throw new InvalidArgumentException('Type de document invalide.');$dir=APP_ROOT.'/storage/application-documents';if(!is_dir($dir)&&!mkdir($dir,0700,true))throw new RuntimeException('Dossier de stockage inaccessible.');$stored=bin2hex(random_bytes(20)).'.'.$ext;if(!move_uploaded_file($f['tmp_name'],$dir.'/'.$stored))throw new RuntimeException('Impossible de stocker le fichier.');$name=mb_substr(basename(str_replace('\\','/',$f['name'])),0,255);$s=db()->prepare('INSERT INTO application_documents(application_id,document_type,original_name,stored_name,mime_type) VALUES (?,?,?,?,?)');try{$s->execute([$id,$type,$name,$stored,$mime]);}catch(Throwable $e){unlink($dir.'/'.$stored);throw $e;}return;}
 throw new InvalidArgumentException('Action inconnue.');
}
function app_children(string $table,int $id):array{if(!in_array($table,['application_events','application_contacts','application_interviews','application_reminders','application_documents'],true))return [];$s=db()->prepare('SELECT * FROM '.$table.' WHERE application_id=? ORDER BY id DESC');$s->execute([$id]);return $s->fetchAll();}
